import {writeFile,rename} from 'node:fs/promises';import {join,resolve} from 'node:path';import {pathToFileURL} from 'node:url';import {createHash} from 'node:crypto';
import {bundleFixture} from './dsh-bundle.mjs';
import {planFixture} from './plans.mjs';import {authoredDshFamily} from './dsh-family-project.mjs';
const {importDshProject}=await import(pathToFileURL(resolve(process.env.AUGMENTOR_PI_TEST_ROOT??'.','dist/runtime/src/dsh-project-import.js')));
const hash=b=>createHash('sha256').update(b).digest('hex');
export async function archivedFixture(t,{bundle=false,historical=false}={}){const f=await planFixture(t,{policy:'read-only'});await f.stop();await rename(f.state,f.state+'-before-import');const rich=await authoredDshFamily(f.workspace);let bytes=JSON.stringify(rich.value),source=join(f.root,'authored-family.json');if(historical){const {historicalFixture}=await import('./dsh-historical-project.mjs'),exported=await historicalFixture(t,()=>rich);bytes=exported.raw.toString();source=exported.source;}else if(bundle){const exported=await bundleFixture(t,()=>rich);bytes=exported.raw.toString();source=exported.source;}else await writeFile(source,bytes,{mode:0o600});const receipt=await importDshProject(source,f.state,{sourceSha256:hash(bytes),selection:f.selection});await f.start();const sid=receipt.sessions[0].sessionId,link=await f.link();return {...f,...rich,receipt,sid,sourceBytes:bytes,url:link.url};}
export async function harnessRpc(link,method,params={}){const u=new URL(link),token=new URLSearchParams(u.hash.slice(1)).get('token'),r=await fetch(u.origin+'/api/rpc',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify({id:crypto.randomUUID(),method,params})}),body=await r.json();if(body.error)throw Error(body.error.message);return body.result;}
